#include <stdint.h>
#include <FreeRTOS.h>
#include "task.h"
#include "app_tasks.h"
#include "stm32f4xx.h"


static void FPU_Enable(void)
{
    *(volatile uint32_t *)0xE000ED88U |= (0xFU << 20U);
    __asm volatile ("dsb");
    __asm volatile ("isb");
}


/*
Simple Blue LED and RED Toggle Using Free RTOS
BlueLED Toggle at 1sec Interval
RedLED toggle at 500ms Interval
*/


void BlueLED_Init()
{
	GPIO_PinConf_t GPIOD_PinConf = {GPIO_PIN_NUM_15,GPIO_MODE_OUTPUT,GPIO_OutType_PP,GPIO_OutSpeed_Low,GPIO_NO_PUPD};
	GPIOD_CLK_ENB();
	GPIO_Init(GPIOD,GPIOD_PinConf);


	GPIOD_PinConf.GPIO_PinNumber=GPIO_PIN_NUM_15;
	GPIO_Init(GPIOD,GPIOD_PinConf);
}


void RedLED_Init()
{
	GPIO_PinConf_t GPIOD_PinConf = {GPIO_PIN_NUM_14,GPIO_MODE_OUTPUT,GPIO_OutType_PP,GPIO_OutSpeed_Low,GPIO_NO_PUPD};
	GPIOD_CLK_ENB();
	GPIO_Init(GPIOD,GPIOD_PinConf);


	GPIOD_PinConf.GPIO_PinNumber=GPIO_PIN_NUM_14;
	GPIO_Init(GPIOD,GPIOD_PinConf);
}




static LedTaskConfig_t redConfig =
{
    .GPIO_PinNumber = GPIO_PIN_NUM_14,
    .delayMs = 500
};

static LedTaskConfig_t blueConfig =
{
    .GPIO_PinNumber = GPIO_PIN_NUM_15,
    .delayMs = 1000
};



static StreamBufferHandle_t gnss_rx_stream;


void Streamer_Init(void)
{
    gnss_rx_stream = xStreamBufferCreate(
        512,
        1
    );

    if (gnss_rx_stream == NULL)
    {
       // Error_Handler();
    }
}

void CAN_GPIO_Init()
{
	GPIO_PinConf_t CAN_TX_RX;

	CAN_TX_RX.GPIO_PinNumber=GPIO_PIN_NUM_8;
	CAN_TX_RX.GPIO_PinMode=GPIO_MODE_ALT;
	CAN_TX_RX.GPIO_OutType=GPIO_OutType_PP;
	CAN_TX_RX.GPIO_OutSpeed=GPIO_OutSpeed_Fast;
	CAN_TX_RX.GPIO_PUPD=GPIO_NO_PUPD;
	CAN_TX_RX.GPIO_AltFnc=GPIO_AF9;


	GPIOB_CLK_ENB();
	GPIO_Init(GPIOB,CAN_TX_RX);

	CAN_TX_RX.GPIO_PinNumber=GPIO_PIN_NUM_9;
	GPIO_Init(GPIOB,CAN_TX_RX);

}


void USART2_Init(void)
{
	GPIO_PinConf_t USART_Pin;
	USART_Pin.GPIO_PinMode=GPIO_MODE_ALT;
	USART_Pin.GPIO_PUPD=GPIO_NO_PUPD;
	USART_Pin.GPIO_OutType=GPIO_OutType_PP;
	USART_Pin.GPIO_OutSpeed=GPIO_OutSpeed_Fast;
	USART_Pin.GPIO_AltFnc=GPIO_AF7;
	GPIOA_CLK_ENB();

	USART_Pin.GPIO_PinNumber=GPIO_PIN_NUM_2;
	GPIO_Init(GPIOA,USART_Pin);
	USART_Pin.GPIO_PinNumber=GPIO_PIN_NUM_3;
	GPIO_Init(GPIOA,USART_Pin);

	USART_Conf_t USART2_Conf;
	USART2_Conf.Mode=USART_MODE_RX_TX;
	USART2_Conf.Parity=USART_PARITY_NONE;
	USART2_Conf.StopBits=USART_STOPBITS_1;
	USART2_Conf.WordLenght=USART_WORDLENGTH_8B;
	USART2_Conf.OverSampleing=0U; /*OverSampling by 16*/
	USART2_Conf.BaudRate=USART_BAUDRATE_9600;
	USART2_CLK_ENB();
	USART_Init(USART2,USART2_Conf);


	NVIC_SetPriority(USART2_IRQn,0U);
	NVIC_EnableIRQ(USART2_IRQn);
	USART2_RXNEIE_ENB();





}


TaskHandle_t gnss_parser_task_handle;

int main(void)
{
    FPU_Enable();
    RedLED_Init();
    BlueLED_Init();
    Streamer_Init();
    CAN_GPIO_Init();
    CAN_Init();
    USART2_Init();

    //xTaskCreate(vLEDToggleTask,"BlueLED", 256,&blueConfig,1, NULL );
    xTaskCreate(GNSS_ParserTask,"GNSS_Parser",512,gnss_rx_stream, 3,&gnss_parser_task_handle);
    xTaskCreate(CAN_TransmitTask,"CANTransmitTask", 256,NULL,2, NULL );

    vTaskStartScheduler();
    while (1);
}


void vApplicationMallocFailedHook(void)
{
    __disable_irq();

    GPIO_WritePin(GPIOD, GPIO_PIN_NUM_14, GPIO_PIN_HIGH);

    while (1);
}



void USART2_IRQHandler(void)
{

	if(USART2->SR & (1U<<5U)) //Check if RXNE Flag is Set
	{
		uint8_t RxData = USART2->DR;

		BaseType_t higher_priority_task_woken = pdFALSE;

		size_t bytes_sent = xStreamBufferSendFromISR(gnss_rx_stream, &RxData, sizeof(RxData), &higher_priority_task_woken );

		if (bytes_sent == 0)
		{
			//RingBufferOverflow++;
		}

		portYIELD_FROM_ISR(higher_priority_task_woken);
     }
}



